descriptor.templateCss:
.kvt-root{height:100%;box-sizing:border-box;font-family:'Mulish',Roboto,'Helvetica Neue',sans-serif;color:#24302A;background:#fff;border:1px solid #DCE3DA;border-radius:12px;box-shadow:0 1px 3px rgba(36,48,42,.08);overflow:hidden;display:flex;flex-direction:column;-webkit-font-smoothing:antialiased}
.kvt-root *{box-sizing:border-box}
.kvt-tabsbar{display:flex;flex-wrap:wrap;align-items:flex-end;gap:4px 12px;padding:0 12px;border-bottom:1px solid #DCE3DA;flex:0 0 auto}
.kvt-tabs{display:flex;gap:4px}
.kvt-tab{min-height:42px;padding:0 16px;border:0;background:transparent;font-family:inherit;font-size:14px;font-weight:800;color:#5A534D;border-bottom:3px solid transparent;margin-bottom:-1px;cursor:pointer}
.kvt-tab:hover{color:#24302A}
.kvt-tab.sel{color:#24302A;border-bottom-color:#33513A;cursor:default}
.kvt-live{margin-left:auto;padding-bottom:13px;font-size:13px;color:#4F6B5C;font-weight:700;display:inline-flex;align-items:center;gap:8px}
.kvt-dot{width:8px;height:8px;border-radius:50%;background:#6E8A12;display:inline-block;box-shadow:0 0 0 3px rgba(110,138,18,.18)}
.kvt-toolbar{flex:1 1 auto;padding:8px 14px;display:flex;flex-wrap:wrap;gap:8px 20px;align-items:center;align-content:center;background:#FAFBF9;overflow:auto}
.kvt-weekbar{align-items:center}
.kvt-note{font-size:13px;color:#3D3833}
.kvt-link{margin-left:auto;min-height:34px;padding:0 14px;border:1px solid #C9D3C7;background:#fff;color:#24302A;border-radius:8px;font-family:inherit;font-size:13px;font-weight:700;display:inline-flex;align-items:center;gap:8px;cursor:pointer}
.kvt-link:hover{border-color:#33513A}
.kvt-group{display:flex;flex-direction:row;align-items:center;gap:8px}
.kvt-glabel{font-size:10px;font-weight:800;letter-spacing:1px;text-transform:uppercase;color:#5A534D}
.kvt-pills{display:flex;flex-wrap:wrap;gap:5px}
.kvt-pill{min-height:32px;padding:0 10px;border-radius:7px;font-family:inherit;font-size:12.5px;font-weight:700;border:1px solid #C9D3C7;background:#fff;color:#24302A;cursor:pointer}
.kvt-pill:hover{border-color:#33513A}
.kvt-pill.sel{border-color:#33513A;background:#33513A;color:#fff}
.kvt-dates{display:flex;align-items:center;gap:6px}
.kvt-dates span{font-size:13px;color:#5A534D}
.kvt-date{min-height:32px;padding:0 8px;border:1px solid #C9D3C7;background:#fff;border-radius:7px;font-family:inherit;font-size:12.5px;color:#24302A}
.kvt-toggle{min-height:34px;padding:0 12px;border-radius:999px;font-family:inherit;font-size:13px;font-weight:700;display:inline-flex;align-items:center;gap:8px;border:1px solid #C9D3C7;background:#fff;color:#24302A;cursor:pointer}
.kvt-tdot{width:12px;height:12px;border-radius:50%;border:2px solid #2F5D8A;background:#fff;display:inline-block}
.kvt-toggle.on{border-color:#2F5D8A;background:#E4EDF7}
.kvt-toggle.on .kvt-tdot{background:#2F5D8A}
.kvt-actions{margin-left:auto;display:flex;align-items:center;gap:8px;padding:4px 0}
.kvt-range{margin-left:auto;align-self:center;font-size:12.5px;font-weight:700;color:#3D3833;white-space:nowrap}
.kvt-btn{min-height:34px;padding:0 14px;border:0;background:#33513A;color:#fff;border-radius:8px;font-family:inherit;font-size:13px;font-weight:700;display:inline-flex;align-items:center;gap:8px;cursor:pointer}
.kvt-btn:hover{background:#26402D}
.kvt-btn.busy{opacity:.6;cursor:progress}
.kvt-tab:focus-visible,.kvt-pill:focus-visible,.kvt-btn:focus-visible,.kvt-toggle:focus-visible,.kvt-link:focus-visible{outline:2px solid #2F5D8A;outline-offset:2px}
@media (max-width:700px){.kvt-live,.kvt-range{display:none}.kvt-tab{padding:0 12px}.kvt-link{margin-left:0}.kvt-actions{margin-left:0;padding-bottom:8px}}

descriptor.controllerScript:
// Kuvio · Pestañas y periodo
// Barra "Última semana / Histórico" que cambia la ventana de tiempo de las gráficas
// nativas de la misma pantalla (line_chart, bar_chart, time_series_chart...).
//
// Cada gráfica puede llevar en su config.settings:
//   kuvioAgg    : agregación en el histórico (AVG, SUM, MAX, MIN). Por defecto: barras SUM, líneas AVG.
//   kuvioWeekTw : ventana de tiempo de "Última semana" (si no existe, se usa la que tenga al cargar).
// Ajustes del widget: inicioCampana (mes 1-12, por defecto 3), diasSemana (por defecto 7).

var DAY = 86400000;
var MES = ['ene','feb','mar','abr','may','jun','jul','ago','sep','oct','nov','dic'];
var ICON_DL = '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M12 4v11M7 10l5 5 5-5M5 20h14"/></svg>';
var ICON_ARROW = '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M5 12h14M13 6l6 6-6 6"/></svg>';

function clone(o) { return o == null ? o : JSON.parse(JSON.stringify(o)); }
function esc(s) { return String(s == null ? '' : s).replace(/[&<>"']/g, function (c) { return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]; }); }
function midnight(t) { var d = new Date(t); d.setHours(0,0,0,0); return d.getTime(); }
function addDays(t, n) { var d = new Date(t); d.setDate(d.getDate() + n); return d.getTime(); }
function addYears(t, n) { var d = new Date(t); d.setFullYear(d.getFullYear() + n); return d.getTime(); }
function dshort(t) { var d = new Date(t); return d.getDate() + ' ' + MES[d.getMonth()]; }
function dlong(t) { var d = new Date(t); return d.getDate() + ' ' + MES[d.getMonth()] + ' ' + d.getFullYear(); }
function isoDate(t) { var d = new Date(t); return d.getFullYear() + '-' + ('0' + (d.getMonth() + 1)).slice(-2) + '-' + ('0' + d.getDate()).slice(-2); }
function parseIso(s) { var p = String(s || '').split('-'); if (p.length !== 3) return null; return new Date(+p[0], +p[1] - 1, +p[2]).getTime(); }

self.onInit = function () {
  var ctx = self.ctx;
  if (!document.getElementById('kv-fonts')) {
    var l = document.createElement('link'); l.id = 'kv-fonts'; l.rel = 'stylesheet';
    l.href = 'https://fonts.googleapis.com/css2?family=Playfair+Display:wght@700&family=Mulish:wght@400;600;700;800&display=swap';
    document.head.appendChild(l);
  }
  var root = ctx.$container[0].querySelector('.kvt-root') || ctx.$container[0];
  var settings = ctx.settings || {};
  var mesCampana = parseInt(settings.inicioCampana, 10) || 3;
  var diasSemana = parseInt(settings.diasSemana, 10) || 7;

  var S = {tab: 'semana', preset: '90d', agg: 'auto', cmp: false, from: null, to: null};
  var created = null, stamp = 0;
  var api = self._kvt = {timers: []};

  // ---------- gráficas de la pantalla ----------
  function charts() {
    var dws = ctx.dashboard && ctx.dashboard.dashboardWidgets;
    var list = dws ? (dws.dashboardWidgets || Array.from(dws)) : [];
    return list.filter(function (dw) {
      var w = dw && dw.widget;
      if (!w || dw.widgetContext === ctx) return false;
      var isChart = /chart/i.test(w.typeFullFqn || '') || w.type === 'timeseries';
      return isChart && w.config && w.config.useDashboardTimewindow === false;
    });
  }

  function calcRango() {
    var now = Date.now(), hoy = midnight(now), start, end = now, label;
    if (S.preset === '30d') { start = addDays(hoy, -29); label = '30 días'; }
    else if (S.preset === '90d') { start = addDays(hoy, -89); label = '90 días'; }
    else if (S.preset === '12m') { start = addDays(addYears(hoy, -1), 1); label = '12 meses'; }
    else if (S.preset === 'camp') {
      var d = new Date(hoy), y = d.getMonth() + 1 >= mesCampana ? d.getFullYear() : d.getFullYear() - 1;
      start = new Date(y, mesCampana - 1, 1).getTime(); label = 'Campaña ' + y;
    } else if (S.preset === 'todo') {
      start = created ? midnight(created) : addDays(hoy, -730); label = 'Desde instalación';
    } else {
      start = parseIso(S.from) || addDays(hoy, -89);
      end = Math.min(now, addDays(parseIso(S.to) || hoy, 1) - 1);
      if (end <= start) end = addDays(start, 1) - 1;
      label = 'Personalizado';
    }
    var days = Math.max(1, Math.round((end - start) / DAY));
    var mode = S.agg !== 'auto' ? S.agg : (days <= 92 ? 'day' : (days <= 400 ? 'week' : 'month'));
    return {start: start, end: end, days: days, mode: mode, label: label};
  }

  function weekTw(dw) {
    var st = dw.widget.config.settings || (dw.widget.config.settings = {});
    if (!st.kuvioWeekTw) st.kuvioWeekTw = clone(dw.widget.config.timewindow);
    return clone(st.kuvioWeekTw);
  }
  function aggOf(dw) {
    var st = dw.widget.config.settings || {};
    if (st.kuvioAgg) return st.kuvioAgg;
    return /bar/i.test(dw.widget.typeFullFqn || '') ? 'SUM' : 'AVG';
  }
  function histTw(dw, R) {
    var base = weekTw(dw);
    var interval = R.mode === 'day' ? DAY : (R.mode === 'week' ? 'WEEK_ISO' : 'MONTH');
    return {
      hideAggregation: false, hideAggInterval: false, hideTimezone: base.hideTimezone || false,
      selectedTab: 1,
      realtime: base.realtime,
      history: {historyType: 1, fixedTimewindow: {startTimeMs: R.start, endTimeMs: R.end}, interval: interval,
        hideInterval: false, hideLastInterval: false, hideFixedInterval: false, hideQuickInterval: false},
      aggregation: {type: aggOf(dw), limit: 25000},
      timezone: base.timezone || null
    };
  }

  function applyTo(dw, R) {
    var cfg = dw.widget.config, wctx = dw.widgetContext;
    var tw = S.tab === 'semana' ? weekTw(dw) : histTw(dw, R);
    var cmp = S.tab === 'hist' && S.cmp;
    cfg.settings = cfg.settings || {};
    var cmpChanged = !!cfg.settings.comparisonEnabled !== cmp;
    var typeChanged = (cfg.timewindow && cfg.timewindow.selectedTab) !== tw.selectedTab;
    cfg.settings.comparisonEnabled = cmp;
    cfg.settings.timeForComparison = 'years';
    if (wctx && wctx.settings && wctx.settings !== cfg.settings) { wctx.settings.comparisonEnabled = cmp; wctx.settings.timeForComparison = 'years'; }
    cfg.timewindow = tw;
    var subs = wctx && wctx.subscriptions ? Object.keys(wctx.subscriptions).map(function (k) { return wctx.subscriptions[k]; }) : [];
    if (!subs.length) return; // aún no ha arrancado: usará cfg.timewindow al iniciarse
    var hasCmp = subs.some(function (s) { return s.options && s.options.comparisonEnabled; });
    if (cmpChanged || ((cmp || hasCmp) && typeChanged)) {
      var s0 = wctx.defaultSubscription || subs[0];
      if (s0 && s0.callbacks && s0.callbacks.forceReInit) { s0.callbacks.forceReInit(); return; }
    }
    subs.forEach(function (s) {
      if (s.useDashboardTimewindow) return;
      s.updateTimewindowConfig(clone(tw));
      if (s.callbacks && s.callbacks.timeWindowUpdated) s.callbacks.timeWindowUpdated(s, clone(tw));
    });
  }

  function applyAll(force) {
    var R = calcRango();
    stamp++;
    var key = S.tab + '|' + (S.tab === 'hist' ? [S.preset, S.from, S.to, R.mode, S.cmp, created ? 1 : 0].join('|') : '');
    var run = function () {
      charts().forEach(function (dw) {
        if (!force && dw.__kvtKey === key) return;
        if (!dw.__kvtKey && S.tab === 'semana' && !(dw.widget.config.settings || {}).comparisonEnabled &&
            JSON.stringify(dw.widget.config.timewindow) === JSON.stringify(weekTw(dw))) {
          // ya está en su ventana semanal: no recargar
          weekTw(dw); dw.__kvtKey = key; return;
        }
        try { applyTo(dw, R); dw.__kvtKey = key; } catch (e) { console.error('[Kuvio pestañas]', e); }
      });
    };
    if (ctx.ngZone) ctx.ngZone.run(run); else run();
    force = false;
  }

  // ---------- CSV ----------
  function http(url) {
    return new Promise(function (res, rej) { ctx.http.get(url).subscribe(function (r) { res(r); }, function (e) { rej(e); }); });
  }
  function entity() {
    var ds = (ctx.datasources && ctx.datasources[0]) || null;
    return ds && ds.entityId ? {id: ds.entityId, type: ds.entityType, name: ds.entityLabel || ds.entityName} : null;
  }
  function csv() {
    var ent = entity(), R = calcRango();
    if (!ent) return;
    var btn = root.querySelector('[data-act="csv"]');
    if (btn) { btn.disabled = true; btn.classList.add('busy'); }
    var iv = R.mode === 'day' ? DAY : (R.mode === 'week' ? 7 * DAY : 30 * DAY);
    var it = R.mode === 'day' ? '' : '&intervalType=' + (R.mode === 'week' ? 'WEEK_ISO' : 'MONTH') + '&timeZone=' + encodeURIComponent(Intl.DateTimeFormat().resolvedOptions().timeZone || 'Europe/Madrid');
    var cols = [], jobs = [];
    charts().forEach(function (dw) {
      var cfg = dw.widget.config, agg = aggOf(dw), keys = [];
      (cfg.datasources || []).forEach(function (ds) { (ds.dataKeys || []).forEach(function (k) { if (k.type === 'timeseries') keys.push(k); }); });
      if (!keys.length) return;
      var q = '/api/plugins/telemetry/' + ent.type + '/' + ent.id + '/values/timeseries?keys=' + encodeURIComponent(keys.map(function (k) { return k.name; }).join(',')) +
        '&startTs=' + R.start + '&endTs=' + R.end + '&interval=' + iv + it + '&agg=' + agg + '&limit=50000&orderBy=ASC&useStrictDataTypes=true';
      jobs.push(http(q).then(function (r) {
        keys.forEach(function (k) {
          cols.push({name: (cfg.title || '') + ' · ' + (k.label || k.name) + ' [' + agg.toLowerCase() + ']', pts: (r && r[k.name]) || []});
        });
      }));
    });
    Promise.all(jobs).then(function () {
      var map = {}, sep = ';';
      var bucket = function (ts) {
        var d = new Date(ts);
        if (R.mode === 'day') return midnight(ts);
        if (R.mode === 'week') { var m = midnight(ts); return addDays(m, -((d.getDay() + 6) % 7)); }
        return new Date(d.getFullYear(), d.getMonth(), 1).getTime();
      };
      cols.forEach(function (c, i) { c.pts.forEach(function (p) { var b = bucket(p.ts); (map[b] = map[b] || {})[i] = p.value; }); });
      var lines = ['Sensor' + sep + (ent.name || ''), 'Periodo' + sep + dlong(R.start) + ' - ' + dlong(R.end),
        'Agregación' + sep + ({day: 'diaria', week: 'semanal', month: 'mensual'})[R.mode], ''];
      lines.push(['Fecha'].concat(cols.map(function (c) { return '"' + c.name.replace(/"/g, '""') + '"'; })).join(sep));
      Object.keys(map).map(Number).sort(function (a, b) { return a - b; }).forEach(function (t) {
        lines.push([isoDate(t)].concat(cols.map(function (c, i) {
          var v = map[t][i]; if (v == null || v === '') return '';
          var n = typeof v === 'number' ? v : parseFloat(v); return isNaN(n) ? String(v) : String(Math.round(n * 1000) / 1000).replace('.', ',');
        })).join(sep));
      });
      var blob = new Blob(['﻿' + lines.join('\r\n')], {type: 'text/csv;charset=utf-8'});
      var a = document.createElement('a');
      a.href = URL.createObjectURL(blob);
      a.download = String(ent.name || 'sensor').replace(/[^\w\-]+/g, '_') + '_historico_' + isoDate(R.start) + '_' + isoDate(R.end) + '.csv';
      document.body.appendChild(a); a.click();
      setTimeout(function () { URL.revokeObjectURL(a.href); a.remove(); }, 500);
    }).catch(function (e) { console.error('[Kuvio pestañas] CSV', e); })
      .then(function () { if (btn) { btn.disabled = false; btn.classList.remove('busy'); } });
  }

  // ---------- dibujo ----------
  function render() {
    var now = Date.now(), R = calcRango();
    var tabs = [['semana', 'Última semana'], ['hist', 'Histórico']].map(function (t) {
      var sel = S.tab === t[0];
      return '<button type="button" role="tab" class="kvt-tab' + (sel ? ' sel' : '') + '" aria-selected="' + sel + '" data-act="tab" data-v="' + t[0] + '">' + t[1] + '</button>';
    }).join('');
    var h = '<div class="kvt-tabsbar"><div class="kvt-tabs" role="tablist" aria-label="Periodo">' + tabs + '</div>';
    if (S.tab === 'semana') {
      h += '<span class="kvt-live"><span class="kvt-dot"></span>En directo · ' + dshort(addDays(midnight(now), -(diasSemana - 1))) + ' – ' + dshort(now) + '</span></div>';
      h += '<div class="kvt-toolbar kvt-weekbar"><span class="kvt-note">Las gráficas muestran los últimos ' + diasSemana + ' días con los datos tal como llegan del sensor.</span>' +
        '<button type="button" class="kvt-link" data-act="tab" data-v="hist">Consultar otros periodos' + ICON_ARROW + '</button></div>';
    } else {
      var presets = [['30d', '30 días'], ['90d', '90 días'], ['camp', 'Campaña'], ['12m', '12 meses'], ['todo', 'Desde instalación'], ['custom', 'Personalizado']];
      var aggs = [['auto', 'Auto'], ['day', 'Día'], ['week', 'Semana'], ['month', 'Mes']];
      h += '<div class="kvt-actions">' +
        '<button type="button" class="kvt-toggle' + (S.cmp ? ' on' : '') + '" aria-pressed="' + S.cmp + '" data-act="cmp"><span class="kvt-tdot"></span>Comparar con año anterior</button>' +
        '<button type="button" class="kvt-btn" data-act="csv">' + ICON_DL + 'Descargar CSV</button></div></div>';
      h += '<div class="kvt-toolbar">' +
        '<div class="kvt-group"><span class="kvt-glabel">Rango</span><div class="kvt-pills">' + presets.map(function (p) {
          var sel = S.preset === p[0], lab = p[0] === 'camp' && sel ? R.label : p[1];
          return '<button type="button" class="kvt-pill' + (sel ? ' sel' : '') + '" aria-pressed="' + sel + '" data-act="preset" data-v="' + p[0] + '">' + esc(lab) + '</button>';
        }).join('') + '</div></div>' +
        '<div class="kvt-group"><span class="kvt-glabel">Fechas</span><div class="kvt-dates">' +
          '<input class="kvt-date" type="date" aria-label="Desde" data-act="from" value="' + isoDate(R.start) + '" max="' + isoDate(now) + '">' +
          '<span>a</span><input class="kvt-date" type="date" aria-label="Hasta" data-act="to" value="' + isoDate(R.end) + '" max="' + isoDate(now) + '"></div></div>' +
        '<div class="kvt-group"><span class="kvt-glabel">Agregación</span><div class="kvt-pills">' + aggs.map(function (a) {
          var sel = S.agg === a[0], lab = a[0] === 'auto' && sel ? 'Auto (' + ({day: 'día', week: 'semana', month: 'mes'})[R.mode] + ')' : a[1];
          return '<button type="button" class="kvt-pill' + (sel ? ' sel' : '') + '" aria-pressed="' + sel + '" data-act="agg" data-v="' + a[0] + '">' + lab + '</button>';
        }).join('') + '</div></div>' +
        '<span class="kvt-range">' + esc(dlong(R.start)) + ' – ' + esc(dlong(R.end)) + '</span>' +
        '</div>';
    }
    root.innerHTML = h;
  }

  function update() { render(); applyAll(false); }

  root.addEventListener('click', function (e) {
    var b = e.target.closest && e.target.closest('[data-act]');
    if (!b || b.tagName === 'INPUT') return;
    var act = b.getAttribute('data-act'), val = b.getAttribute('data-v');
    if (act === 'tab') { if (S.tab === val) return; S.tab = val; update(); }
    else if (act === 'preset') {
      if (val === 'custom' && S.preset !== 'custom') { var R0 = calcRango(); S.from = isoDate(R0.start); S.to = isoDate(R0.end); }
      S.preset = val; update();
    }
    else if (act === 'agg') { S.agg = val; update(); }
    else if (act === 'cmp') { S.cmp = !S.cmp; update(); }
    else if (act === 'csv') csv();
  });
  root.addEventListener('change', function (e) {
    var act = e.target.getAttribute && e.target.getAttribute('data-act');
    if (act !== 'from' && act !== 'to') return;
    var R0 = calcRango();
    if (S.preset !== 'custom') { S.from = isoDate(R0.start); S.to = isoDate(R0.end); S.preset = 'custom'; }
    if (act === 'from') S.from = e.target.value; else S.to = e.target.value;
    update();
  });

  // fecha de alta del sensor para "Desde instalación"
  var ent = entity();
  if (ent && (ent.type === 'DEVICE' || ent.type === 'ASSET')) {
    http('/api/' + ent.type.toLowerCase() + '/' + ent.id).then(function (r) { created = r && r.createdTime; if (S.preset === 'todo') update(); }).catch(function () {});
  }

  render();
  // Las gráficas pueden arrancar después que este widget: se repasa varias veces al inicio
  [0, 400, 1200, 2500, 5000].forEach(function (ms) { api.timers.push(setTimeout(function () { applyAll(false); }, ms)); });
  api.reapply = function () { applyAll(false); };
};

self.onDataUpdated = function () {};
self.onResize = function () {};
self.onDestroy = function () { if (self._kvt) self._kvt.timers.forEach(clearTimeout); };
self.typeParameters = function () { return {maxDatasources: 1, maxDataKeys: 1, dataKeysOptional: true, singleEntity: true}; };
